#define SOKOL_IMPL
#include "sokol_app.h"
#include "sokol_gfx.h"
#include "sokol_glue.h"
#include "sokol_log.h"
#include "rect.h"   // generated by: sokol-shdc --input rect.glsl --output rect.h --slang glsl430:hlsl5:metal_macos

#include <stdint.h>
#include <stddef.h>
#include <assert.h>

// ─────────────────────────────────────────────────────────────────────────────
// Instance data — 64 bytes, one cache line per rect
// ─────────────────────────────────────────────────────────────────────────────

#define MAX_INSTANCES 4096

struct RectInstance
{
    float x, y, w, h; // 16B
    float radii[4]; // 16B
    uint8_t color[4]; //  4B
    uint8_t border_color[4]; //  4B
    float border_width; //  4B
    float shadow_softness; //  4B
    float clip[4]; // 16B
    uint8_t layer; //  1B
    uint8_t _pad[3]; //  3B
    float _reserved[13]; // 52B  ← room for tex coords, material id, etc
};


// ─────────────────────────────────────────────────────────────────────────────
// Renderer
// ─────────────────────────────────────────────────────────────────────────────

struct RectRenderer
{
    sg_pipeline pip;
    sg_bindings bind;
    sg_buffer instance_buf;
    sg_pass_action pass_action;
    RectInstance instances[MAX_INSTANCES];
    int instance_count;
};

static RectRenderer r;

// ── Color helpers ─────────────────────────────────────────────────────────────

// Pack 0xRRGGBBAA into uint8[4]
static void color_hex(uint8_t out[4], uint32_t rgba)
{
    out[0] = (rgba >> 24) & 0xFF; // R
    out[1] = (rgba >> 16) & 0xFF; // G
    out[2] = (rgba >> 8) & 0xFF; // B
    out[3] = (rgba >> 0) & 0xFF; // A
}

// ── Init ──────────────────────────────────────────────────────────────────────

void rect_renderer_init(RectRenderer& r)
{
    // Instance buffer — written every frame from CPU
    sg_buffer_desc buf_desc = {};
    buf_desc.size = MAX_INSTANCES * sizeof(RectInstance);
    buf_desc.usage.dynamic_update = true;
    buf_desc.label = "rect-instances";
    r.instance_buf = sg_make_buffer(buf_desc);

    // Shader — generated header provides rect_shader_desc()
    sg_shader shd = sg_make_shader(rect_shader_desc(sg_query_backend()));

    // Pipeline
    sg_pipeline_desc pip_desc = {};
    pip_desc.shader = shd;
    pip_desc.primitive_type = SG_PRIMITIVETYPE_TRIANGLE_STRIP;
    pip_desc.label = "rect-pipeline";

    // All instance data comes from buffer slot 0, one step per instance
    pip_desc.layout.buffers[0].stride = sizeof(RectInstance);
    pip_desc.layout.buffers[0].step_func = SG_VERTEXSTEP_PER_INSTANCE;

    // Attribute locations must match layout(location=N) in rect.glsl
    pip_desc.layout.attrs[0] = {.offset = offsetof(RectInstance, x), .format = SG_VERTEXFORMAT_FLOAT2}; // i_pos
    pip_desc.layout.attrs[1] = {.offset = offsetof(RectInstance, w), .format = SG_VERTEXFORMAT_FLOAT2}; // i_size
    pip_desc.layout.attrs[2] = {.offset = offsetof(RectInstance, radii), .format = SG_VERTEXFORMAT_FLOAT4}; // i_radii
    pip_desc.layout.attrs[3] = {.offset = offsetof(RectInstance, color), .format = SG_VERTEXFORMAT_UBYTE4N}; // i_color
    pip_desc.layout.attrs[4] = {
        .offset = offsetof(RectInstance, border_color), .format = SG_VERTEXFORMAT_UBYTE4N
    }; // i_border_color
    pip_desc.layout.attrs[5] = {
        .offset = offsetof(RectInstance, border_width), .format = SG_VERTEXFORMAT_FLOAT
    }; // i_border_width
    pip_desc.layout.attrs[6] = {.offset = offsetof(RectInstance, clip), .format = SG_VERTEXFORMAT_FLOAT4}; // i_clip

    pip_desc.layout.attrs[7] = {
        .offset = offsetof(RectInstance, shadow_softness),
        .format = SG_VERTEXFORMAT_FLOAT
    };

    // Standard alpha blending
    pip_desc.colors[0].blend.enabled = true;
    pip_desc.colors[0].blend.src_factor_rgb = SG_BLENDFACTOR_SRC_ALPHA;
    pip_desc.colors[0].blend.dst_factor_rgb = SG_BLENDFACTOR_ONE_MINUS_SRC_ALPHA;
    pip_desc.colors[0].blend.src_factor_alpha = SG_BLENDFACTOR_ONE;
    pip_desc.colors[0].blend.dst_factor_alpha = SG_BLENDFACTOR_ONE_MINUS_SRC_ALPHA;

    r.pip = sg_make_pipeline(pip_desc);

    // Bind the instance buffer to vertex buffer slot 0
    r.bind.vertex_buffers[0] = r.instance_buf;

    // Clear to dark background
    r.pass_action.colors[0].load_action = SG_LOADACTION_CLEAR;
    r.pass_action.colors[0].clear_value = {0.1f, 0.1f, 0.2f, 1.0f};
}

// ── Push ──────────────────────────────────────────────────────────────────────

void rect_push(RectRenderer& r, const RectInstance& inst)
{
    assert(r.instance_count < MAX_INSTANCES && "increase MAX_INSTANCES");
    r.instances[r.instance_count++] = inst;
}

// ── Flush ─────────────────────────────────────────────────────────────────────

void rect_flush(RectRenderer& r)
{
    if (r.instance_count == 0) return;

    // Upload instance data
    sg_update_buffer(r.instance_buf, sg_range{
                         .ptr = r.instances,
                         .size = (size_t)(r.instance_count * sizeof(RectInstance)),
                     });

    // Upload resolution uniform (binding=0 in rect.glsl)
    vs_params_t vs_params = {
        .u_resolution = {(float)sapp_width(), (float)sapp_height()}
    };
    sg_apply_pipeline(r.pip);
    sg_apply_bindings(&r.bind);
    sg_apply_uniforms(0, SG_RANGE(vs_params)); // slot 0 = layout(binding=0)

    // 4 verts (triangle strip quad) × N instances
    sg_draw(0, 4, r.instance_count);

    r.instance_count = 0;
}

// ─────────────────────────────────────────────────────────────────────────────
// App
// ─────────────────────────────────────────────────────────────────────────────

static void init(void)
{
    sg_desc desc = {};
    desc.environment = sglue_environment();
    desc.logger.func = slog_func;
    sg_setup(&desc);

    rect_renderer_init(r);
}

static void frame(void)
{
    // ── Push test rects ───────────────────────────────────────────────────────


    // Parent container — this is the visible "scroll panel"
    RectInstance panel = {};
    panel.x = 100;
    panel.y = 100;
    panel.w = 200;
    panel.h = 150;
    panel.radii[0] = panel.radii[1] = panel.radii[2] = panel.radii[3] = 8.0f;
    color_hex(panel.color, 0x222233FF);
    color_hex(panel.border_color, 0x8888AAFF);
    panel.border_width = 1.5f;
    // panel itself is not clipped
    RectInstance shadow = {};
    float spread = 10.0f;
    shadow.x = panel.x - spread;
    shadow.y = panel.y - spread;
    shadow.w = panel.w + spread * 2;
    shadow.h = panel.h + spread * 2;
    memcpy(shadow.radii, panel.radii, sizeof(panel.radii));
    color_hex(shadow.color, 0x00000099);
    shadow.shadow_softness = 100.0f;
    rect_push(r, shadow);
    rect_push(r, panel);

    // Child rect — larger than the panel, should be clipped to panel bounds
    // clip[0..3] = panel's inner bounds (inset by border so it looks clean)
    RectInstance child = {};
    child.x = 80;
    child.y = 120; // starts OUTSIDE the panel on the left
    child.w = 280;
    child.h = 60; // wider than the panel too
    child.radii[0] = child.radii[1] = child.radii[2] = child.radii[3] = 8.0f;
    color_hex(child.color, 0xFF6633FF);
    color_hex(child.border_color, 0xFF9966FF);
    child.border_width = 1.5f;
    // clip = panel's interior
    child.clip[0] = 101; // panel.x + border
    child.clip[1] = 101; // panel.y + border
    child.clip[2] = 198; // panel.w - border*2
    child.clip[3] = 148; // panel.h - border*2
    rect_push(r, child);
    RectInstance outline = {};
    outline.x = 400;
    outline.y = 100;
    outline.w = 200;
    outline.h = 150;
    outline.radii[0] = outline.radii[1] = outline.radii[2] = outline.radii[3] = 8.0f;
    color_hex(outline.color, 0x00000000);
    color_hex(outline.border_color, 0xffffffff);
    outline.border_width = 5.0f;
    rect_push(r, outline);

    // ── Draw ──────────────────────────────────────────────────────────────────
    sg_begin_pass({.action = r.pass_action, .swapchain = sglue_swapchain()});
    rect_flush(r);
    sg_end_pass();
    sg_commit();
}

static void cleanup(void)
{
    sg_shutdown();
}

sapp_desc sokol_main(int argc, char* argv[])
{
    (void)argc;
    (void)argv;
    sapp_desc desc = {};
    desc.init_cb = init;
    desc.frame_cb = frame;
    desc.cleanup_cb = cleanup;
    desc.width = 800;
    desc.height = 600;
    desc.window_title = "EmberGUI";
    desc.logger.func = slog_func;
    return desc;
}
